  { id: 'char-l1-m-01-2', type: 'mystery', characterId: 'adam', category: 'Personnages', difficulty: 'expert', answer: 'Adam', clues: ['Reçoit une mission concernant la terre et les animaux.','Adam connaissait directement Jéhovah et reçut de lui des instructions précises, mais il finit par désobéir et perdre sa position approuvée.','Adam reçut de Jéhovah une vie parfaite et une mission précise.'], explanation: 'Adam reçut de Jéhovah une vie parfaite et une mission précise.', reference: 'Genèse 1:26-31' },
  { id: 'char-l1-m-02-1', type: 'mystery', characterId: 'noe', category: 'Personnages', difficulty: 'hard', answer: 'Noé', clues: ['Noé était un homme juste qui vivait dans une génération profondément corrompue. Jéhovah lui ordonna de construire une arche et le préserva, lui et sa famille, du Déluge.','Région située entre l’Éden et l’Ararat, puis les environs des montagnes d’Ararat après le Déluge.','Foi'], explanation: 'Noé marcha avec le vrai Dieu alors que la majorité de son époque s’éloignait de lui.', reference: 'Genèse 6:9-22' },
  { id: 'char-l1-m-02-2', type: 'mystery', characterId: 'noe', category: 'Personnages', difficulty: 'expert', answer: 'Noé', clues: ['Il marche avec le vrai Dieu.','Noé est décrit comme marchant avec Dieu. Sa foi se manifesta par une obéissance concrète aux instructions reçues.','Noé marcha avec le vrai Dieu alors que la majorité de son époque s’éloignait de lui.'], explanation: 'Noé marcha avec le vrai Dieu alors que la majorité de son époque s’éloignait de lui.', reference: 'Genèse 6:9-22' },
  { id: 'char-l1-m-03-1', type: 'mystery', characterId: 'abraham', category: 'Personnages', difficulty: 'hard', answer: 'Abraham', clues: ['Abraham était le patriarche à qui Jéhovah promit une descendance et une bénédiction pour toutes les nations. Il quitta Our et vécut ensuite comme résident étranger en Canaan.','Our, Harân, Canaan et plusieurs régions du Proche-Orient.','Foi'], explanation: 'Abraham quitta sa patrie sur la base d’une promesse divine.', reference: 'Genèse 12:1-9' },
  { id: 'char-l1-m-03-2', type: 'mystery', characterId: 'abraham', category: 'Personnages', difficulty: 'expert', answer: 'Abraham', clues: ['Il quitte Our puis Harân sur instruction de Jéhovah.','Abraham développa une relation de confiance avec Jéhovah et est appelé « ami de Jéhovah » en raison de sa foi et de son obéissance.','Abraham quitta sa patrie sur la base d’une promesse divine.'], explanation: 'Abraham quitta sa patrie sur la base d’une promesse divine.', reference: 'Genèse 12:1-9' },
  { id: 'char-l1-m-04-1', type: 'mystery', characterId: 'sarah', category: 'Personnages', difficulty: 'hard', answer: 'Sara', clues: ['Épouse d’Abraham et mère d’Isaac — Sarah a vécu les promesses faites à Abraham et est devenue mère d’Isaac malgré son âge avancé.','Our, Harân, Canaan et plusieurs régions parcourues avec Abraham.','Foi'], explanation: 'Sara accepta de quitter sa patrie avec Abraham.', reference: 'Genèse 11:29-32' },
  { id: 'char-l1-m-04-2', type: 'mystery', characterId: 'sarah', category: 'Personnages', difficulty: 'expert', answer: 'Sara', clues: ['Quitte Harân avec Abraham.','Sara plaça sa confiance dans la promesse divine et est citée parmi les femmes de foi dans les Écritures chrétiennes.','Sara accepta de quitter sa patrie avec Abraham.'], explanation: 'Sara accepta de quitter sa patrie avec Abraham.', reference: 'Genèse 11:29-32' },
  { id: 'char-l1-m-05-1', type: 'mystery', characterId: 'jacob', category: 'Personnages', difficulty: 'hard', answer: 'Jacob', clues: ['Jacob était le fils d’Isaac et de Rébecca, frère jumeau d’Ésaü et père des douze fils à l’origine des tribus d’Israël.','Canaan, Paddan-Aram et de nouveau Canaan; il descendit ensuite en Égypte avec sa famille.','Persévérance'], explanation: 'Jacob dut apprendre à faire confiance à Jéhovah au milieu de conflits familiaux.', reference: 'Genèse 27:1-45' },
  { id: 'char-l1-m-05-2', type: 'mystery', characterId: 'jacob', category: 'Personnages', difficulty: 'expert', answer: 'Jacob', clues: ['Il obtient le droit d’aînesse et la bénédiction.','Jéhovah apparut à Jacob, renouvela avec lui l’alliance abrahamique et resta avec lui malgré ses épreuves et ses imperfections.','Jacob dut apprendre à faire confiance à Jéhovah au milieu de conflits familiaux.'], explanation: 'Jacob dut apprendre à faire confiance à Jéhovah au milieu de conflits familiaux.', reference: 'Genèse 27:1-45' },
  { id: 'char-l1-m-06-1', type: 'mystery', characterId: 'joseph', category: 'Personnages', difficulty: 'hard', answer: 'Joseph', clues: ['Joseph était le fils de Jacob et de Rachel qui fut vendu comme esclave par ses frères avant de devenir administrateur en Égypte et de sauver de nombreuses vies pendant une famine.','Canaan puis Égypte.','Intégrité'], explanation: 'Joseph resta fidèle malgré la trahison et l’injustice.', reference: 'Genèse 37:1-36' },
  { id: 'char-l1-m-06-2', type: 'mystery', characterId: 'joseph', category: 'Personnages', difficulty: 'expert', answer: 'Joseph', clues: ['Ses frères le vendent comme esclave.','Joseph attribua à Jéhovah le mérite de ses capacités et resta fidèle dans des circonstances où personne de sa famille ne pouvait le surveiller.','Joseph resta fidèle malgré la trahison et l’injustice.'], explanation: 'Joseph resta fidèle malgré la trahison et l’injustice.', reference: 'Genèse 37:1-36' },
  { id: 'char-l1-m-07-1', type: 'mystery', characterId: 'moise', category: 'Personnages', difficulty: 'hard', answer: 'Moïse', clues: ['Prophète et médiateur d’Israël — Moïse conduit Israël hors d’Égypte et reçoit la Loi au mont Sinaï.','Égypte, désert du Sinaï et régions à l’est du Jourdain.','Humilité'], explanation: 'Moïse accepta une mission qu’il jugeait humainement très difficile.', reference: 'Exode 3:1-22' },
  { id: 'char-l1-m-07-2', type: 'mystery', characterId: 'moise', category: 'Personnages', difficulty: 'expert', answer: 'Moïse', clues: ['Affronte Pharaon avec Aaron.','Moïse entretenait une relation exceptionnellement proche avec Jéhovah; la Bible dit qu’il lui parlait « face à face » au sens d’une relation directe et privilégiée.','Moïse accepta une mission qu’il jugeait humainement très difficile.'], explanation: 'Moïse accepta une mission qu’il jugeait humainement très difficile.', reference: 'Exode 3:1-22' },
  { id: 'char-l1-m-08-1', type: 'mystery', characterId: 'josue', category: 'Personnages', difficulty: 'hard', answer: 'Josué', clues: ['Josué, fils de Noun, servit Moïse avant de lui succéder comme dirigeant d’Israël. Il conduisit le peuple dans la conquête et la répartition de la Terre promise.','Désert du Sinaï, Canaan et territoire d’Israël.','Courage'], explanation: 'Josué servit longtemps aux côtés de Moïse avant de recevoir davantage de responsabilités.', reference: 'Josué 1:1-18' },
  { id: 'char-l1-m-08-2', type: 'mystery', characterId: 'josue', category: 'Personnages', difficulty: 'expert', answer: 'Josué', clues: ['Il combat les Amaléqites sous la direction de Moïse.','Josué comptait sur Jéhovah pour diriger Israël et exhorta le peuple à le servir fidèlement jusqu’à la fin de sa vie.','Josué servit longtemps aux côtés de Moïse avant de recevoir davantage de responsabilités.'], explanation: 'Josué servit longtemps aux côtés de Moïse avant de recevoir davantage de responsabilités.', reference: 'Josué 1:1-18' },
  { id: 'char-l1-m-09-1', type: 'mystery', characterId: 'ruth', category: 'Personnages', difficulty: 'hard', answer: 'Ruth', clues: ['Ruth était une Moabite devenue veuve qui choisit de rester avec sa belle-mère Naomi et d’adorer Jéhovah. Elle devint l’épouse de Boaz et une ancêtre de David.','Moab puis Bethléhem en Juda.','Loyauté'], explanation: 'Ruth manifesta un attachement exceptionnel à Noémi et à Jéhovah.', reference: 'Ruth 1:1-22' },
  { id: 'char-l1-m-09-2', type: 'mystery', characterId: 'ruth', category: 'Personnages', difficulty: 'expert', answer: 'Ruth', clues: ['Après la mort de son mari, elle refuse d’abandonner Naomi.','Ruth choisit Jéhovah comme son Dieu et s’attacha au peuple de Naomi. Sa fidélité et sa confiance en Jéhovah furent ensuite bénies.','Ruth manifesta un attachement exceptionnel à Noémi et à Jéhovah.'], explanation: 'Ruth manifesta un attachement exceptionnel à Noémi et à Jéhovah.', reference: 'Ruth 1:1-22' },
  { id: 'char-l1-m-10-1', type: 'mystery', characterId: 'samuel', category: 'Personnages', difficulty: 'hard', answer: 'Samuel', clues: ['Samuel était prophète, juge et serviteur de Jéhovah dès son enfance. Il joua un rôle majeur dans la transition d’Israël vers la royauté.','Silo, Rama et différents lieux d’Israël.','Écoute'], explanation: 'Samuel apprit à écouter Jéhovah dès son enfance.', reference: '1 Samuel 1:24-28' },
  { id: 'char-l1-m-10-2', type: 'mystery', characterId: 'samuel', category: 'Personnages', difficulty: 'expert', answer: 'Samuel', clues: ['Hanna le consacre au service de Jéhovah avant sa naissance.','Samuel grandit auprès de Jéhovah et fut reconnu comme prophète; il resta attaché à la volonté divine pendant toute sa vie.','Samuel apprit à écouter Jéhovah dès son enfance.'], explanation: 'Samuel apprit à écouter Jéhovah dès son enfance.', reference: '1 Samuel 1:24-28' },
  { id: 'char-l1-m-11-1', type: 'mystery', characterId: 'david', category: 'Personnages', difficulty: 'hard', answer: 'David', clues: ['Roi d’Israël — David a servi comme roi d’Israël et a connu à la fois de grandes victoires et de graves erreurs.','Bethléem, Juda, Jérusalem et le royaume d’Israël.','Courage'], explanation: 'David développa sa confiance en Jéhovah alors qu’il gardait les moutons.', reference: '1 Samuel 16:1-13' },
  { id: 'char-l1-m-11-2', type: 'mystery', characterId: 'david', category: 'Personnages', difficulty: 'expert', answer: 'David', clues: ['Affronte Goliath.','David avait une foi profonde en Jéhovah, même s’il commit de graves péchés. Il accepta la correction et revint sincèrement vers Dieu.','David développa sa confiance en Jéhovah alors qu’il gardait les moutons.'], explanation: 'David développa sa confiance en Jéhovah alors qu’il gardait les moutons.', reference: '1 Samuel 16:1-13' },
  { id: 'char-l1-m-12-1', type: 'mystery', characterId: 'salomon', category: 'Personnages', difficulty: 'hard', answer: 'Salomon', clues: ['Roi et bâtisseur du temple — Salomon demande de la sagesse et construit le temple de Jérusalem, mais sa fin de règne comporte aussi de graves problèmes.','Jérusalem et le royaume d’Israël.','Sagesse'], explanation: 'Salomon demanda d’abord la sagesse plutôt que la richesse ou une longue vie.', reference: '1 Rois 3:5-28' },
  { id: 'char-l1-m-12-2', type: 'mystery', characterId: 'salomon', category: 'Personnages', difficulty: 'expert', answer: 'Salomon', clues: ['Demande de la sagesse pour gouverner.','Salomon demanda à Jéhovah un cœur obéissant pour juger son peuple. Jéhovah lui accorda une sagesse remarquable, mais Salomon finit par laisser ses femmes détourner son cœur vers le faux culte.','Salomon demanda d’abord la sagesse plutôt que la richesse ou une longue vie.'], explanation: 'Salomon demanda d’abord la sagesse plutôt que la richesse ou une longue vie.', reference: '1 Rois 3:5-28' },
  { id: 'char-l1-m-13-1', type: 'mystery', characterId: 'elie', category: 'Personnages', difficulty: 'hard', answer: 'Élie', clues: ['Élie était un prophète de Jéhovah qui combattit avec courage le culte de Baal dans le royaume d’Israël.','Shilo et le territoire d’Israël; il servait au tabernacle à Shilo.','Courage'], explanation: 'Éliya annonça avec courage les jugements de Jéhovah malgré l’opposition d’Achab et de Jézabel.', reference: '1 Samuel 2:12-36' },
  { id: 'char-l1-m-13-2', type: 'mystery', characterId: 'elie', category: 'Personnages', difficulty: 'expert', answer: 'Élie', clues: ['Il annonce une sécheresse au temps d’Achab.','Éli servait comme grand prêtre devant Jéhovah et transmit à Samuel comment répondre à l’appel divin. Mais Jéhovah le condamna parce qu’il honorait ses fils plus que lui en ne les disciplinant pas suffisamment.','Éliya annonça avec courage les jugements de Jéhovah malgré l’opposition d’Achab et de Jézabel.'], explanation: 'Éliya annonça avec courage les jugements de Jéhovah malgré l’opposition d’Achab et de Jézabel.', reference: '1 Samuel 2:12-36' },
  { id: 'char-l1-m-14-1', type: 'mystery', characterId: 'esther', category: 'Personnages', difficulty: 'hard', answer: 'Esther', clues: ['Esther, aussi appelée Hadassa, était une Juive devenue reine de Perse. Elle risqua sa vie pour intervenir en faveur de son peuple menacé d’extermination.','Suse, capitale de l’empire perse.','Courage'], explanation: 'Observer son courage et sa prudence devant le roi.', reference: 'Esther 2:5-20' },
  { id: 'char-l1-m-14-2', type: 'mystery', characterId: 'esther', category: 'Personnages', difficulty: 'expert', answer: 'Esther', clues: ['Elle devient reine sans révéler d’abord son origine juive.','Bien que le nom de Jéhovah ne figure pas directement dans le livre, Esther est présentée comme une fidèle servante du vrai Dieu. Elle agit avec foi, maîtrise de soi et courage pour défendre le peuple de Dieu.','Observer son courage et sa prudence devant le roi.'], explanation: 'Observer son courage et sa prudence devant le roi.', reference: 'Esther 2:5-20' },
  { id: 'char-l1-m-15-1', type: 'mystery', characterId: 'daniel', category: 'Personnages', difficulty: 'hard', answer: 'Daniel', clues: ['Daniel était un jeune Juif emmené à Babylone. Il servit dans plusieurs administrations impériales tout en restant fidèle à Jéhovah.','Juda puis Babylone; Suse apparaît aussi dans le cadre d’une vision.','Intégrité'], explanation: 'Étudier son refus de se souiller avec les aliments du roi.', reference: 'Daniel 1:3-20' },
  { id: 'char-l1-m-15-2', type: 'mystery', characterId: 'daniel', category: 'Personnages', difficulty: 'expert', answer: 'Daniel', clues: ['Il refuse de se souiller avec les aliments du roi.','Daniel priait régulièrement, recherchait la compréhension auprès de Jéhovah et resta fidèle malgré les complots.','Étudier son refus de se souiller avec les aliments du roi.'], explanation: 'Étudier son refus de se souiller avec les aliments du roi.', reference: 'Daniel 1:3-20' },
  { id: 'char-l1-m-16-1', type: 'mystery', characterId: 'jean-baptiste', category: 'Personnages', difficulty: 'hard', answer: 'Jean le Baptiseur', clues: ['Précurseur de Jésus — Jean prépare les personnes au ministère de Jésus et appelle à la repentance.','Désert de Judée et région du Jourdain.','Courage'], explanation: 'Étudier son rôle annoncé à l’avance pour préparer le chemin du Messie.', reference: 'Matthieu 3:1-17' },
  { id: 'char-l1-m-16-2', type: 'mystery', characterId: 'jean-baptiste', category: 'Personnages', difficulty: 'expert', answer: 'Jean le Baptiseur', clues: ['Prêche et baptise.','Jean dirigeait l’attention vers Jésus et accomplissait la mission que Jéhovah lui avait confiée.','Étudier son rôle annoncé à l’avance pour préparer le chemin du Messie.'], explanation: 'Étudier son rôle annoncé à l’avance pour préparer le chemin du Messie.', reference: 'Matthieu 3:1-17' },
  { id: 'char-l1-m-17-1', type: 'mystery', characterId: 'marie', category: 'Personnages', difficulty: 'hard', answer: 'Marie', clues: ['Marie est la mère de Jésus. Elle est une descendante de David et a accepté avec foi la mission extraordinaire qui lui a été confiée.','Nazareth, Bethléem, Galilée et Jérusalem.','Foi'], explanation: 'Marie accepta avec humilité une mission qui allait bouleverser sa vie.', reference: 'Luc 1:26-56' },
  { id: 'char-l1-m-17-2', type: 'mystery', characterId: 'marie', category: 'Personnages', difficulty: 'expert', answer: 'Marie', clues: ['Elle reçoit l’annonce de la naissance de Jésus.','Marie se soumit humblement à la volonté de Jéhovah et manifesta une foi profonde dans les promesses concernant son fils.','Marie accepta avec humilité une mission qui allait bouleverser sa vie.'], explanation: 'Marie accepta avec humilité une mission qui allait bouleverser sa vie.', reference: 'Luc 1:26-56' },
  { id: 'char-l1-m-18-1', type: 'mystery', characterId: 'pierre', category: 'Personnages', difficulty: 'hard', answer: 'Pierre', clues: ['Apôtre — Pierre est l’un des principaux apôtres et joue un rôle important dans les débuts de la congrégation chrétienne.','Galilée, Jérusalem, Judée et lieux de prédication.','Zèle'], explanation: 'Étudier son évolution entre impulsivité et foi mûre.', reference: 'Matthieu 4:18-22' },
  { id: 'char-l1-m-18-2', type: 'mystery', characterId: 'pierre', category: 'Personnages', difficulty: 'expert', answer: 'Pierre', clues: ['Suit Jésus.','Pierre apprit à compter sur Jéhovah par l’intermédiaire de Jésus et devint ensuite un prédicateur courageux.','Étudier son évolution entre impulsivité et foi mûre.'], explanation: 'Étudier son évolution entre impulsivité et foi mûre.', reference: 'Matthieu 4:18-22' },
  { id: 'char-l1-m-19-1', type: 'mystery', characterId: 'paul', category: 'Personnages', difficulty: 'hard', answer: 'Paul', clues: ['Apôtre et missionnaire — Paul est passé de persécuteur des disciples à prédicateur zélé du christianisme.','Tarse, Jérusalem, Syrie, Asie Mineure, Macédoine, Grèce, Rome et autres régions.','Zèle'], explanation: 'Paul changea radicalement de conduite après avoir compris la volonté de Jésus.', reference: 'Actes 9:1-30' },
  { id: 'char-l1-m-19-2', type: 'mystery', characterId: 'paul', category: 'Personnages', difficulty: 'expert', answer: 'Paul', clues: ['Est arrêté sur le chemin de Damas par une vision du Christ.','Paul considérait son ministère comme une responsabilité reçue de Jésus et consacra sa vie à annoncer la bonne nouvelle et à fortifier les congrégations.','Paul changea radicalement de conduite après avoir compris la volonté de Jésus.'], explanation: 'Paul changea radicalement de conduite après avoir compris la volonté de Jésus.', reference: 'Actes 9:1-30' },
  { id: 'char-l1-m-20-1', type: 'mystery', characterId: 'jean', category: 'Personnages', difficulty: 'hard', answer: 'Jean', clues: ['Apôtre de Jésus et rédacteur biblique, frère de Jacques fils de Zébédée. Il faisait partie des trois apôtres particulièrement proches de Jésus.','Galilée, Jérusalem et Patmos; la fin de son activité est traditionnellement associée à Éphèse.','Amour'], explanation: 'Observer son évolution entre zèle impulsif et amour chrétien.', reference: 'Marc 3:13-19' },
  { id: 'char-l1-m-20-2', type: 'mystery', characterId: 'jean', category: 'Personnages', difficulty: 'expert', answer: 'Jean', clues: ['Il abandonne son activité de pêcheur pour suivre Jésus.','Jean consacra sa longue vie à transmettre le témoignage sur Jésus et à enseigner l’amour pour Dieu et les frères.','Observer son évolution entre zèle impulsif et amour chrétien.'], explanation: 'Observer son évolution entre zèle impulsif et amour chrétien.', reference: 'Marc 3:13-19' }
